NAME                 TEXT                                                                                                                                                                               
-------------------- --------------------------------------------------------------------------------------------------------------------------------------------                                       
UPDATED_RX_CNT       PROCEDURE UPDATED_RX_CNT                                                                                                                                                           
                     (                                                                                                                                                                                  
                       IN_MSG_REF_ID IN VARCHAR2                                                                                                                                                        
                     ) AS                                                                                                                                                                               
                         L_MS_ID NUMBER;                                                                                                                                                                
                         L_CNT NUMBER;                                                                                                                                                                  
                         L_GIR_CNT NUMBER;                                                                                                                                                              
                         L_AMEND_CNT NUMBER;                                                                                                                                                            
                     BEGIN                                                                                                                                                                              
                         BEGIN                                                                                                                                                                          
                             SELECT M.MS_ID, COUNT(1) INTO L_MS_ID, L_GIR_CNT FROM GIR_MSG_SPEC M, GIR_FILING_INFO F                                                                                    
                             WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                          
                             AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                           
                             GROUP BY M.MS_ID;                                                                                                                                                          
                         EXCEPTION                                                                                                                                                                      
                             WHEN NO_DATA_FOUND THEN                                                                                                                                                    
                                 L_GIR_CNT := 0;                                                                                                                                                        
                         END;                                                                                                                                                                           
                                                                                                                                                                                                        
                         IF L_GIR_CNT >= 0 THEN                                                                                                                                                         
                             UPDATE GIR_MSG_SPEC SET GIR_CNT = L_GIR_CNT WHERE MS_ID = L_MS_ID;                                                                                                         
                             COMMIT;                                                                                                                                                                    
                         END IF;                                                                                                                                                                        
                                                                                                                                                                                                        
                         BEGIN                                                                                                                                                                          
                             WITH AMEND_SRC AS (                                                                                                                                                        
                                 --                                                                                                                                                                     
                                 --  M.MSG_TYPE_IND = 'GIR_102'                                                                                                                                         
                                 --                                                                                                                                                                     
                                 SELECT M.MS_ID, F.FI_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, GIR_FILING_INFO F                                                                              
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_102'                                                                                                                 
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FI_ID                                                                                                                                              
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 --                                                                                                                                                                     
                                 --  M.MSG_TYPE_IND = 'GIR_101'                                                                                                                                         
                                 --                                                                                                                                                                     
                                 SELECT M.MS_ID, F.FI_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, GIR_FILING_INFO F                                                                              
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_2','OECD_12','OECD_3','OECD_13')                                                   
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FI_ID                                                                                                                                              
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 SELECT M.MS_ID, F.FI_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, GIR_FILING_INFO F, GIR_GEN_SEC X                                                               
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_0','OECD_10')                                                                      
                                 AND F.FI_ID = X.FI_ID AND X.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                                                       
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FI_ID                                                                                                                                              
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 SELECT M.MS_ID, F.FI_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, GIR_FILING_INFO F, GIR_JDX_SEC X                                                               
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_0','OECD_10')                                                                      
                                 AND F.FI_ID = X.FI_ID AND X.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                                                       
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FI_ID                                                                                                                                              
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 SELECT M.MS_ID, F.FI_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, GIR_FILING_INFO F, GIR_SMRY X                                                                  
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_0','OECD_10')                                                                      
                                 AND F.FI_ID = X.FI_ID AND X.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                                                       
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FI_ID                                                                                                                                              
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 SELECT M.MS_ID, F.FI_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, GIR_FILING_INFO F, GIR_UTPR_ATTR X                                                             
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_0','OECD_10')                                                                      
                                 AND F.FI_ID = X.FI_ID AND X.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                                                       
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FI_ID                                                                                                                                              
                             ), AMEND_MAX AS (                                                                                                                                                          
                                 SELECT MS_ID, FI_ID, MAX(CNT) AS MAX_CNT FROM AMEND_SRC GROUP BY MS_ID, FI_ID                                                                                          
                             ) SELECT MS_ID, SUM(MAX_CNT) INTO L_MS_ID, L_AMEND_CNT FROM AMEND_MAX GROUP BY MS_ID;                                                                                      
                         EXCEPTION                                                                                                                                                                      
                             WHEN NO_DATA_FOUND THEN                                                                                                                                                    
                                 L_AMEND_CNT := 0;                                                                                                                                                      
                         END;                                                                                                                                                                           
                                                                                                                                                                                                        
                         IF L_AMEND_CNT >= 0 THEN                                                                                                                                                       
                             UPDATE GIR_MSG_SPEC SET AMEND_CNT = L_AMEND_CNT WHERE MS_ID = L_MS_ID;                                                                                                     
                             COMMIT;                                                                                                                                                                    
                         END IF;                                                                                                                                                                        
                                                                                                                                                                                                        
                                                                                                                                                                                                        
                     END UPDATED_RX_CNT;                                                                                                                                                                
UPDATED_TX_CNT       PROCEDURE UPDATED_TX_CNT                                                                                                                                                           
                     (                                                                                                                                                                                  
                       IN_MSG_REF_ID IN VARCHAR2                                                                                                                                                        
                     ) AS                                                                                                                                                                               
                         L_MS_ID NUMBER;                                                                                                                                                                
                         L_CNT NUMBER;                                                                                                                                                                  
                         L_GIR_CNT NUMBER;                                                                                                                                                              
                         L_AMEND_CNT NUMBER;                                                                                                                                                            
                     BEGIN                                                                                                                                                                              
                         BEGIN                                                                                                                                                                          
                             SELECT M.MS_ID, COUNT(1) INTO L_MS_ID, L_GIR_CNT FROM GIR_MSG_SPEC M, FILING_INFO F                                                                                        
                             WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                          
                             AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                           
                             GROUP BY M.MS_ID;                                                                                                                                                          
                         EXCEPTION                                                                                                                                                                      
                             WHEN NO_DATA_FOUND THEN                                                                                                                                                    
                                 L_GIR_CNT := 0;                                                                                                                                                        
                         END;                                                                                                                                                                           
                                                                                                                                                                                                        
                         IF L_GIR_CNT >= 0 THEN                                                                                                                                                         
                             UPDATE GIR_MSG_SPEC SET GIR_CNT = L_GIR_CNT WHERE MS_ID = L_MS_ID;                                                                                                         
                             COMMIT;                                                                                                                                                                    
                         END IF;                                                                                                                                                                        
                                                                                                                                                                                                        
                         BEGIN                                                                                                                                                                          
                             WITH AMEND_SRC AS (                                                                                                                                                        
                                 --                                                                                                                                                                     
                                 --  M.MSG_TYPE_IND = 'GIR_102'                                                                                                                                         
                                 --                                                                                                                                                                     
                                 SELECT M.MS_ID, F.FILING_INFO_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, FILING_INFO F                                                                         
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_102'                                                                                                                 
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FILING_INFO_ID                                                                                                                                     
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 --                                                                                                                                                                     
                                 --  M.MSG_TYPE_IND = 'GIR_101'                                                                                                                                         
                                 --                                                                                                                                                                     
                                 SELECT M.MS_ID, F.FILING_INFO_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, FILING_INFO F                                                                         
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_2','OECD_12','OECD_3','OECD_13')                                                   
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FILING_INFO_ID                                                                                                                                     
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 SELECT M.MS_ID, F.FILING_INFO_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, FILING_INFO F, GEN_SEC X                                                              
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_0','OECD_10')                                                                      
                                 AND F.FILING_INFO_ID = X.FILING_INFO_ID AND X.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                                     
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FILING_INFO_ID                                                                                                                                     
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 SELECT M.MS_ID, F.FILING_INFO_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, FILING_INFO F, JDX_SEC X                                                              
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_0','OECD_10')                                                                      
                                 AND F.FILING_INFO_ID = X.FILING_INFO_ID AND X.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                                     
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FILING_INFO_ID                                                                                                                                     
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 SELECT M.MS_ID, F.FILING_INFO_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, FILING_INFO F, SMRY X                                                                 
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_0','OECD_10')                                                                      
                                 AND F.FILING_INFO_ID = X.FILING_INFO_ID AND X.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                                     
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FILING_INFO_ID                                                                                                                                     
                                                                                                                                                                                                        
                                 UNION                                                                                                                                                                  
                                                                                                                                                                                                        
                                 SELECT M.MS_ID, F.FILING_INFO_ID, NVL2(COUNT(1),1,0) AS CNT FROM GIR_MSG_SPEC M, FILING_INFO F, UTPR_ATTR X                                                            
                                 WHERE M.MS_ID = F.MS_ID AND M.MSG_TYPE_IND = 'GIR_101' AND F.DOC_TYPE_IND IN ('OECD_0','OECD_10')                                                                      
                                 AND F.FILING_INFO_ID = X.FILING_INFO_ID AND X.DOC_TYPE_IND IN ('OECD_1','OECD_11')                                                                                     
                                 AND M.MSG_REF_ID = IN_MSG_REF_ID                                                                                                                                       
                                 GROUP BY M.MS_ID, F.FILING_INFO_ID                                                                                                                                     
                             ), AMEND_MAX AS (                                                                                                                                                          
                                 SELECT MS_ID, FILING_INFO_ID, MAX(CNT) AS MAX_CNT FROM AMEND_SRC GROUP BY MS_ID, FILING_INFO_ID                                                                        
                             ) SELECT MS_ID, SUM(MAX_CNT) INTO L_MS_ID, L_AMEND_CNT FROM AMEND_MAX GROUP BY MS_ID;                                                                                      
                         EXCEPTION                                                                                                                                                                      
                             WHEN NO_DATA_FOUND THEN                                                                                                                                                    
                                 L_AMEND_CNT := 0;                                                                                                                                                      
                         END;                                                                                                                                                                           
                                                                                                                                                                                                        
                                                                                                                                                                                                        
                         IF L_AMEND_CNT >= 0 THEN                                                                                                                                                       
                             UPDATE GIR_MSG_SPEC SET AMEND_CNT = L_AMEND_CNT WHERE MS_ID = L_MS_ID;                                                                                                     
                             COMMIT;                                                                                                                                                                    
                         END IF;                                                                                                                                                                        
                                                                                                                                                                                                        
                                                                                                                                                                                                        
                     END UPDATED_TX_CNT;                                                                                                                                                                
UPD_CTS_GSEC_DOC_REF PROCEDURE UPD_CTS_GSEC_DOC_REF                                                                                                                                                     
                     (                                                                                                                                                                                  
                         OUT_RESULT_CODE OUT NUMBER                                                                                                                                                     
                     )                                                                                                                                                                                  
                     AS                                                                                                                                                                                 
                         L_WARNING_FLAGS NUMBER;                                                                                                                                                        
                         L_RECORD_TYPE VARCHAR2(1);                                                                                                                                                     
                         L_CNT NUMBER;                                                                                                                                                                  
                         L_LOG CLOB;                                                                                                                                                                    
                         L_RECORD_COUNT NUMBER := 0;                                                                                                                                                    
                         L_BTL_ID NUMBER;                                                                                                                                                               
                     BEGIN                                                                                                                                                                              
                         INSERT INTO BATCH_LOG VALUES                                                                                                                                                   
                         (BATCH_LOG_SEQ.NEXTVAL, 'UPD_CTS_GSEC_DOC_REF', NULL,                                                                                                                          
                         SYSDATE, NULL, 'R', NULL, NULL, SYSDATE, 2, SYSDATE, 2) RETURNING BTL_ID INTO L_BTL_ID;                                                                                        
                         COMMIT;                                                                                                                                                                        
                                                                                                                                                                                                        
                     --  CREATE NEW COUNTRIES IN CTS_GSEC_DOC_REF FOR ANY NEW RECORDS IN GSEC_DOC_REF                                                                                                   
                         FOR R IN (SELECT DISTINCT A.GSDR_ID, A.GS_ID, B.REC_JDX_CTRY FROM GSEC_DOC_REF A, V_PTP_GSEC_CTRY B, PTP_GEN_SEC C                                                             
                             WHERE A.GS_ID=B.GS_ID AND A.GS_ID=C.GS_ID                                                                                                                                  
                             AND C.DOC_TYPE_IND != 'OECD_3' AND C.DOC_TYPE_IND != 'OECD_13'                                                                                                             
                             AND NOT EXISTS (SELECT 1 FROM V_EXT_GSEC_CTRY C WHERE A.GS_ID=C.GS_ID AND B.REC_JDX_CTRY=C.REC_JDX_CTRY))                                                                  
                         LOOP                                                                                                                                                                           
                             L_RECORD_COUNT := L_RECORD_COUNT + 1;                                                                                                                                      
                                                                                                                                                                                                        
                             -- PRINT PROGRESS TO BATCH LOG                                                                                                                                             
                             IF MOD(L_RECORD_COUNT, 5000) = 0 THEN                                                                                                                                      
                                 UPDATE BATCH_LOG SET APP_LOG = 'PROCESSING RECORD: ' || L_RECORD_COUNT, LAST_UPD_AT = SYSDATE WHERE BTL_ID = L_BTL_ID;                                                 
                                 COMMIT;                                                                                                                                                                
                             END IF;                                                                                                                                                                    
                                                                                                                                                                                                        
                             INSERT INTO CTS_GSEC_DOC_REF                                                                                                                                               
                                 VALUES (R.GSDR_ID, R.REC_JDX_CTRY, NULL, NULL, NULL, NULL, NULL, SYSDATE, 2, SYSDATE, 2);                                                                              
                                                                                                                                                                                                        
                         END LOOP;                                                                                                                                                                      
                                                                                                                                                                                                        
                     --  FIND COUNTRIES THAT ARE DELETED IN PTP AND NOT YET SENT BY CTS, AND THEN SET DELETE_FLAG TO "Y"                                                                                
                         FOR R IN (SELECT A.GSDR_ID, A.REC_JDX_CTRY, A.LAST_DOC_REF_ID FROM V_EXT_GSEC_CTRY A, PTP_GEN_SEC G                                                                            
                             WHERE                                                                                                                                                                      
                             A.GS_ID=G.GS_ID                                                                                                                                                            
                             AND A.LAST_DOC_REF_ID IS NULL AND A.TRANSMISSION_FLAG IS NULL AND (A.DELETE_FLAG != 'Y' OR A.DELETE_FLAG IS NULL)                                                          
                             AND NOT EXISTS (SELECT 1 FROM V_PTP_GSEC_CTRY WHERE A.FCE_TIN = V_PTP_GSEC_CTRY.FCE_TIN AND A.REC_JDX_CTRY = V_PTP_GSEC_CTRY.REC_JDX                                       
                     _CTRY))                                                                                                                                                                            
                                                                                                                                                                                                        
                         LOOP                                                                                                                                                                           
                     		UPDATE CTS_GSEC_DOC_REF                                                                                                                                                          
                     			SET DELETE_FLAG = 'Y',                                                                                                                                                          
                     				LAST_UPD_AT = SYSDATE,                                                                                                                                                         
                     				LAST_UPD_BY = 2                                                                                                                                                                
                     			WHERE GSDR_ID = R.GSDR_ID AND REC_JDX_CTRY = R.REC_JDX_CTRY;                                                                                                                    
                         END LOOP;                                                                                                                                                                      
                                                                                                                                                                                                        
                     -- FIND RECORDS THAT ARE DELETED BY ITS RESIDENCE COUTNRY, BUT STILL HAVE RECORDS NOT MARKED AS DELETED                                                                            
                         FOR R IN (SELECT DISTINCT A.FCE_TIN, A.REC_JDX_CTRY FROM V_EXT_GSEC_CTRY A, PTP_GEN_SEC G, PTP_GEN_REC_JDX H                                                                   
                             WHERE A.GS_ID=G.GS_ID AND G.GS_ID=H.GS_ID AND A.REC_JDX_CTRY=H.REC_JDX_CTRY AND A.DELETE_FLAG = 'Y'                                                                        
                             AND NOT EXISTS                                                                                                                                                             
                                 (SELECT 1 FROM V_EXT_GSEC_CTRY AA, PTP_GEN_SEC GG, PTP_GEN_REC_JDX HH                                                                                                  
                                 WHERE AA.GS_ID=GG.GS_ID AND GG.GS_ID=HH.GS_ID AND AA.DELETE_FLAG IS NULL AND AA.REC_JDX_CTRY=HH.REC_JDX_CTRY                                                           
                                 AND AA.FCE_TIN=A.FCE_TIN AND AA.REC_JDX_CTRY=A.REC_JDX_CTRY)                                                                                                           
                             AND EXISTS                                                                                                                                                                 
                                 (SELECT 1 FROM V_EXT_GSEC_CTRY AAA, PTP_GEN_SEC GGG, PTP_GEN_REC_JDX HHH                                                                                               
                                 WHERE AAA.GS_ID=GGG.GS_ID AND GGG.GS_ID=HHH.GS_ID AND AAA.DELETE_FLAG IS NULL                                                                                          
                                 AND AAA.FCE_TIN=A.FCE_TIN AND AAA.REC_JDX_CTRY=A.REC_JDX_CTRY)                                                                                                         
                                 )                                                                                                                                                                      
                         LOOP                                                                                                                                                                           
                     		UPDATE CTS_GSEC_DOC_REF                                                                                                                                                          
                     			SET DELETE_FLAG = 'Y',                                                                                                                                                          
                     				LAST_UPD_AT = SYSDATE,                                                                                                                                                         
                     				LAST_UPD_BY = 2                                                                                                                                                                
                     			WHERE REC_JDX_CTRY = R.REC_JDX_CTRY AND GSDR_ID IN (                                                                                                                            
                                     SELECT AAA.GSDR_ID FROM V_EXT_GSEC_CTRY AAA, PTP_GEN_SEC GGG, PTP_GEN_REC_JDX HHH                                                                                  
                                     WHERE AAA.GS_ID=GGG.GS_ID AND GGG.GS_ID=HHH.GS_ID AND AAA.DELETE_FLAG IS NULL                                                                                      
                                     AND AAA.FCE_TIN=R.FCE_TIN AND AAA.REC_JDX_CTRY=R.REC_JDX_CTRY);                                                                                                    
                         END LOOP;                                                                                                                                                                      
                                                                                                                                                                                                        
                     --  FIND COUNTRIES THAT ARE RESTORED IN PTP AND THEN SET DELETE_FLAG TO NULL                                                                                                       
                         FOR R IN (SELECT DISTINCT A.GSDR_ID, A.REC_JDX_CTRY FROM V_EXT_GSEC_CTRY A, PTP_GEN_SEC G                                                                                      
                             WHERE A.GS_ID=G.GS_ID                                                                                                                                                      
                             AND A.DELETE_FLAG = 'Y' AND G.DOC_TYPE_IND != 'OECD_3' AND G.DOC_TYPE_IND != 'OECD_13'                                                                                     
                             AND EXISTS (SELECT 1 FROM V_PTP_GSEC_CTRY WHERE V_PTP_GSEC_CTRY.FCE_TIN=A.FCE_TIN AND V_PTP_GSEC_CTRY.REC_JDX_CTRY=A.REC_JDX_CTRY)                                         
                             )                                                                                                                                                                          
                         LOOP                                                                                                                                                                           
                     		UPDATE CTS_GSEC_DOC_REF                                                                                                                                                          
                     			SET DELETE_FLAG = NULL,                                                                                                                                                         
                     				LAST_UPD_AT = SYSDATE,                                                                                                                                                         
                     				LAST_UPD_BY = 2                                                                                                                                                                
                     			WHERE GSDR_ID=R.GSDR_ID AND REC_JDX_CTRY=R.REC_JDX_CTRY;                                                                                                                        
                         END LOOP;                                                                                                                                                                      
                                                                                                                                                                                                        
                         COMMIT;                                                                                                                                                                        
                                                                                                                                                                                                        
                         IF L_RECORD_COUNT > 0 THEN                                                                                                                                                     
                             UPDATE BATCH_LOG SET APP_LOG = L_RECORD_COUNT || ' RECORDS WERE PROCESSED.', JOB_STS = 'S', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSD                                       
                     ATE WHERE BTL_ID = L_BTL_ID;                                                                                                                                                       
                                                                                                                                                                                                        
                             OUT_RESULT_CODE := L_BTL_ID;                                                                                                                                               
                         ELSE                                                                                                                                                                           
                             UPDATE BATCH_LOG SET APP_LOG = 'NO RECORD FOUND.', JOB_STS = 'S', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSDATE WHERE BTL_ID = L_BTL_I                                       
                     D;                                                                                                                                                                                 
                                                                                                                                                                                                        
                             OUT_RESULT_CODE := 0;                                                                                                                                                      
                         END IF;                                                                                                                                                                        
                     	COMMIT;                                                                                                                                                                           
                                                                                                                                                                                                        
                         EXCEPTION                                                                                                                                                                      
                           WHEN OTHERS THEN                                                                                                                                                             
                             OUT_RESULT_CODE := -1;                                                                                                                                                     
                             ROLLBACK;                                                                                                                                                                  
                             UPDATE BATCH_LOG SET ERR_LOG = DBMS_UTILITY.FORMAT_ERROR_STACK, JOB_STS = 'E', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSDATE WHERE BTL                                       
                     _ID = L_BTL_ID;                                                                                                                                                                    
                                                                                                                                                                                                        
                             COMMIT;                                                                                                                                                                    
                     END UPD_CTS_GSEC_DOC_REF;                                                                                                                                                          
UPD_CTS_JSEC_DOC_REF PROCEDURE UPD_CTS_JSEC_DOC_REF                                                                                                                                                     
                     (                                                                                                                                                                                  
                         OUT_RESULT_CODE OUT NUMBER                                                                                                                                                     
                     )                                                                                                                                                                                  
                     AS                                                                                                                                                                                 
                         L_WARNING_FLAGS NUMBER;                                                                                                                                                        
                         L_RECORD_TYPE VARCHAR2(1);                                                                                                                                                     
                         L_CNT NUMBER;                                                                                                                                                                  
                         L_LOG CLOB;                                                                                                                                                                    
                         L_RECORD_COUNT NUMBER := 0;                                                                                                                                                    
                         L_BTL_ID NUMBER;                                                                                                                                                               
                     BEGIN                                                                                                                                                                              
                         INSERT INTO BATCH_LOG VALUES                                                                                                                                                   
                         (BATCH_LOG_SEQ.NEXTVAL, 'UPD_CTS_JSEC_DOC_REF', NULL,                                                                                                                          
                         SYSDATE, NULL, 'R', NULL, NULL, SYSDATE, 2, SYSDATE, 2) RETURNING BTL_ID INTO L_BTL_ID;                                                                                        
                         COMMIT;                                                                                                                                                                        
                                                                                                                                                                                                        
                     --  CREATE NEW COUNTRIES IN CTS_JSEC_DOC_REF FOR ANY NEW RECORDS IN JSEC_DOC_REF                                                                                                   
                         FOR R IN (SELECT DISTINCT A.JSDR_ID, A.JS_ID, B.REC_JDX_CTRY FROM JSEC_DOC_REF A, V_PTP_JSEC_CTRY B, PTP_JDX_SEC C                                                             
                             WHERE A.JS_ID=B.JS_ID AND A.JS_ID=C.JS_ID                                                                                                                                  
                             AND C.DOC_TYPE_IND != 'OECD_3' AND C.DOC_TYPE_IND != 'OECD_13'                                                                                                             
                             AND NOT EXISTS (SELECT 1 FROM V_EXT_JSEC_CTRY C WHERE A.JS_ID=C.JS_ID AND B.REC_JDX_CTRY=C.REC_JDX_CTRY))                                                                  
                         LOOP                                                                                                                                                                           
                             L_RECORD_COUNT := L_RECORD_COUNT + 1;                                                                                                                                      
                                                                                                                                                                                                        
                             -- PRINT PROGRESS TO BATCH LOG                                                                                                                                             
                             IF MOD(L_RECORD_COUNT, 5000) = 0 THEN                                                                                                                                      
