                     --  FIND COUNTRIES THAT ARE DELETED IN PTP AND NOT YET SENT BY CTS, AND THEN SET DELETE_FLAG TO "Y"                                                                                
                         FOR R IN (SELECT A.JSDR_ID, A.REC_JDX_CTRY, A.LAST_DOC_REF_ID FROM V_EXT_JSEC_CTRY A, PTP_JDX_SEC G                                                                            
                             WHERE                                                                                                                                                                      
