                         END LOOP;                                                                                                                                                                      
                                                                                                                                                                                                        
                     -- FIND RECORDS THAT ARE DELETED BY ITS RESIDENCE COUTNRY, BUT STILL HAVE RECORDS NOT MARKED AS DELETED                                                                            
                         FOR R IN (SELECT DISTINCT A.FCE_TIN, A.REC_JDX_CTRY FROM V_EXT_JSEC_CTRY A, PTP_JDX_SEC G, PTP_JDX_REC_JDX H                                                                   
                             WHERE A.JS_ID=G.JS_ID AND G.JS_ID=H.JS_ID AND A.REC_JDX_CTRY=H.REC_JDX_CTRY AND A.DELETE_FLAG = 'Y'                                                                        
