                     				LAST_UPD_BY = 2                                                                                                                                                                
                     			WHERE REC_JDX_CTRY = R.REC_JDX_CTRY AND JSDR_ID IN (                                                                                                                            
                                     SELECT AAA.JSDR_ID FROM V_EXT_JSEC_CTRY AAA, PTP_JDX_SEC GGG, PTP_JDX_REC_JDX HHH                                                                                  
                                     WHERE AAA.JS_ID=GGG.JS_ID AND GGG.JS_ID=HHH.JS_ID AND AAA.DELETE_FLAG IS NULL                                                                                      
