                         ELSE                                                                                                                                                                           
                             UPDATE BATCH_LOG SET APP_LOG = 'NO RECORD FOUND.', JOB_STS = 'S', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSDATE WHERE BTL_ID = L_BTL_I                                       
                     D;                                                                                                                                                                                 
                                                                                                                                                                                                        
                             OUT_RESULT_CODE := 0;                                                                                                                                                      
                         END IF;                                                                                                                                                                        
                     	COMMIT;                                                                                                                                                                           
                                                                                                                                                                                                        
                         EXCEPTION                                                                                                                                                                      
                           WHEN OTHERS THEN                                                                                                                                                             
                             OUT_RESULT_CODE := -1;                                                                                                                                                     
                             ROLLBACK;                                                                                                                                                                  
                             UPDATE BATCH_LOG SET ERR_LOG = DBMS_UTILITY.FORMAT_ERROR_STACK, JOB_STS = 'E', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSDATE WHERE BTL                                       
                     _ID = L_BTL_ID;                                                                                                                                                                    
                                                                                                                                                                                                        
                             COMMIT;                                                                                                                                                                    
                     END UPD_CTS_UTPR_DOC_REF;                                                                                                                                                          
UPD_GSEC_DOC_REF     PROCEDURE UPD_GSEC_DOC_REF                                                                                                                                                         
                     (                                                                                                                                                                                  
                         OUT_RESULT_CODE OUT NUMBER                                                                                                                                                     
                     )                                                                                                                                                                                  
                     AS                                                                                                                                                                                 
                         L_GS_ID NUMBER;                                                                                                                                                                
                         L_GSDR_ID NUMBER;                                                                                                                                                              
                         L_RECORD_TYPE VARCHAR2(1);                                                                                                                                                     
                         L_CTS_RESULT NUMBER;                                                                                                                                                           
                         L_RECORD_COUNT NUMBER := 0;                                                                                                                                                    
                         L_BATCH_LOG_ID NUMBER;                                                                                                                                                         
                                                                                                                                                                                                        
                     BEGIN                                                                                                                                                                              
                         INSERT INTO BATCH_LOG VALUES                                                                                                                                                   
                         (BATCH_LOG_SEQ.NEXTVAL, 'UPD_GSEC_DOC_REF', NULL,                                                                                                                              
                         SYSDATE, NULL, 'R', NULL, NULL, SYSDATE, 2, SYSDATE, 2) RETURNING BTL_ID INTO L_BATCH_LOG_ID;                                                                                  
                         COMMIT;                                                                                                                                                                        
                                                                                                                                                                                                        
                     	FOR R IN (SELECT F.FCE_TIN, B.DOC_REF_ID, B.CORR_DOC_REF_ID, B.FI_ID, B.GS_ID, B.WARNING_FLAGS, B.LAST_UPD_AT, B.CREATED_AT                                                       
                     		FROM PTP_GEN_SEC B, PTP_FILING_INFO F                                                                                                                                            
                             WHERE                                                                                                                                                                      
                             B.FI_ID = F.FI_ID                                                                                                                                                          
                             AND NOT EXISTS (SELECT 1 FROM GSEC_DOC_REF WHERE B.GS_ID = GSEC_DOC_REF.GS_ID)                                                                                             
                             AND B.IS_ACTIVE = 'Y'                                                                                                                                                      
                             ORDER BY B.CREATED_AT ASC                                                                                                                                                  
                             )                                                                                                                                                                          
                     	LOOP                                                                                                                                                                              
                             L_RECORD_COUNT := L_RECORD_COUNT + 1;                                                                                                                                      
                                                                                                                                                                                                        
                             -- print progress to batch log                                                                                                                                             
                             IF MOD(L_RECORD_COUNT, 5000) = 0 THEN                                                                                                                                      
                                 UPDATE BATCH_LOG SET APP_LOG = 'PROCESSING RECORD: ' || L_RECORD_COUNT, LAST_UPD_AT = SYSDATE WHERE BTL_ID = L_BATCH_LOG_ID;                                           
                                 COMMIT;                                                                                                                                                                
                             END IF;                                                                                                                                                                    
                                                                                                                                                                                                        
                     		IF R.WARNING_FLAGS > 0 THEN                                                                                                                                                      
                     			-- Exception                                                                                                                                                                    
                                 L_RECORD_TYPE := 'E';                                                                                                                                                  
                     		ELSE                                                                                                                                                                             
                                 -- To Be Transmitted                                                                                                                                                   
                     			L_RECORD_TYPE := 'T';                                                                                                                                                           
                     		END IF;                                                                                                                                                                          
                                                                                                                                                                                                        
                             -- IF CORR_DOC_REF_ID IS NULL, THEN THIS IS A NEW OECD1 RECORD MISSING IN CTS, INSERT IT                                                                                   
                             IF R.CORR_DOC_REF_ID IS NULL THEN                                                                                                                                          
                                 INSERT INTO GSEC_DOC_REF VALUES                                                                                                                                        
                                 (GSEC_DOC_REF_SEQ.NEXTVAL, R.GS_ID, R.FI_ID, R.FCE_TIN, R.DOC_REF_ID, L_RECORD_TYPE,                                                                                   
                                 R.LAST_UPD_AT, 2, R.CREATED_AT, 2);                                                                                                                                    
                                 CONTINUE;                                                                                                                                                              
                                                                                                                                                                                                        
                             ELSE                                                                                                                                                                       
                                 -- FIND THE GS_ID EXISTS IN CTS FOR THIS RECORD CHAIN                                                                                                                  
                                 L_GS_ID := FIND_CTS_GS_ID(R.FCE_TIN, R.CORR_DOC_REF_ID);                                                                                                               
                                                                                                                                                                                                        
                                 -- IF GS_ID IS FOUND, FIND THE GSDR_ID FOR UPDATING                                                                                                                    
                                 IF L_GS_ID > 0 THEN                                                                                                                                                    
                                     SELECT MAX(GSDR_ID) INTO L_GSDR_ID FROM GSEC_DOC_REF WHERE GS_ID = L_GS_ID;                                                                                        
                                                                                                                                                                                                        
                                     --  UPDATE GSEC_DOC_REF IF RECORD FOUND                                                                                                                            
                                     UPDATE GSEC_DOC_REF                                                                                                                                                
                                         SET DOC_REF_ID = R.DOC_REF_ID,                                                                                                                                 
                                             GS_ID = R.GS_ID,                                                                                                                                           
                                             FI_ID = R.FI_ID,                                                                                                                                           
                                             FCE_TIN = R.FCE_TIN,                                                                                                                                       
                                             RECORD_TYPE = L_RECORD_TYPE,                                                                                                                               
                                             LAST_UPD_AT = SYSDATE,                                                                                                                                     
                                             LAST_UPD_BY = 2                                                                                                                                            
                                         WHERE GSDR_ID = L_GSDR_ID;                                                                                                                                     
                                                                                                                                                                                                        
                                 -- IF GS_ID CANNOT BE FOUND, THEN THE WHOLE RECORD CHAIN IS MISSING IN CTS, JUST INSERT THE CURRENT ACTIVE RECORD                                                      
                                 ELSIF L_GS_ID = -1 THEN                                                                                                                                                
                                     INSERT INTO GSEC_DOC_REF VALUES                                                                                                                                    
                                     (GSEC_DOC_REF_SEQ.NEXTVAL, R.GS_ID, R.FI_ID, R.FCE_TIN, R.DOC_REF_ID, L_RECORD_TYPE,                                                                               
                                     R.LAST_UPD_AT, 2, R.CREATED_AT, 2);                                                                                                                                
                                     CONTINUE;                                                                                                                                                          
                                                                                                                                                                                                        
                                 ELSE                                                                                                                                                                   
                                     RAISE_APPLICATION_ERROR(-20001, 'ERROR OCCURRED IN FIND_CTS_GS_ID');                                                                                               
                                                                                                                                                                                                        
                                 END IF;                                                                                                                                                                
                                                                                                                                                                                                        
                             END IF;                                                                                                                                                                    
                                                                                                                                                                                                        
                         END LOOP;                                                                                                                                                                      
                                                                                                                                                                                                        
                         IF L_RECORD_COUNT > 0 THEN                                                                                                                                                     
                             UPDATE BATCH_LOG SET APP_LOG = L_RECORD_COUNT || ' RECORDS WERE PROCESSED.', JOB_STS = 'S', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSD                                       
                     ATE WHERE BTL_ID = L_BATCH_LOG_ID;                                                                                                                                                 
                                                                                                                                                                                                        
                             OUT_RESULT_CODE := L_BATCH_LOG_ID;                                                                                                                                         
                         ELSE                                                                                                                                                                           
                             UPDATE BATCH_LOG SET APP_LOG = 'NO RECORD FOUND.', JOB_STS = 'S', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSDATE WHERE BTL_ID = L_BATCH                                       
                     _LOG_ID;                                                                                                                                                                           
                                                                                                                                                                                                        
                             OUT_RESULT_CODE := 0;                                                                                                                                                      
                         END IF;                                                                                                                                                                        
                     	COMMIT;                                                                                                                                                                           
                                                                                                                                                                                                        
                         UPD_CTS_GSEC_DOC_REF(L_CTS_RESULT);                                                                                                                                            
                                                                                                                                                                                                        
                         IF L_CTS_RESULT < 0 AND OUT_RESULT_CODE > 0 THEN                                                                                                                               
                             UPDATE BATCH_LOG SET ERR_LOG = 'ERROR OCCURRED IN UPD_CTS_GSEC_DOC_REF' WHERE BTL_ID = L_BATCH_LOG_ID;                                                                     
                         END IF;                                                                                                                                                                        
                                                                                                                                                                                                        
                         EXCEPTION                                                                                                                                                                      
                           WHEN OTHERS THEN                                                                                                                                                             
                             OUT_RESULT_CODE := -1;                                                                                                                                                     
                             ROLLBACK;                                                                                                                                                                  
                             UPDATE BATCH_LOG SET ERR_LOG = DBMS_UTILITY.FORMAT_ERROR_STACK, JOB_STS = 'E', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSDATE WHERE BTL                                       
                     _ID = L_BATCH_LOG_ID;                                                                                                                                                              
                                                                                                                                                                                                        
                             COMMIT;                                                                                                                                                                    
                                                                                                                                                                                                        
                     END UPD_GSEC_DOC_REF;                                                                                                                                                              
