                         COMMIT;                                                                                                                                                                        
                                                                                                                                                                                                        
                     	FOR R IN (SELECT F.FCE_TIN, B.DOC_REF_ID, B.CORR_DOC_REF_ID, B.FI_ID, B.SMRY_ID, B.WARNING_FLAGS                                                                                  
                     		FROM PTP_SMRY B, PTP_FILING_INFO F                                                                                                                                               
