                                     (SMRY_DOC_REF_SEQ.NEXTVAL, R.SMRY_ID, R.FI_ID, R.FCE_TIN, R.DOC_REF_ID, L_RECORD_TYPE,                                                                             
                                     SYSDATE, 2, SYSDATE, 2);                                                                                                                                           
                                     CONTINUE;                                                                                                                                                          
                                                                                                                                                                                                        
