                         IF L_CTS_RESULT < 0 AND OUT_RESULT_CODE > 0 THEN                                                                                                                               
                             UPDATE BATCH_LOG SET ERR_LOG = 'ERROR OCCURRED IN UPD_CTS_SMRY_DOC_REF' WHERE BTL_ID = L_BATCH_LOG_ID;                                                                     
