                         SYSDATE, NULL, 'R', NULL, NULL, SYSDATE, 2, SYSDATE, 2) RETURNING BTL_ID INTO L_BATCH_LOG_ID;                                                                                  
                         COMMIT;                                                                                                                                                                        
                                                                                                                                                                                                        
                     	FOR R IN (SELECT F.FCE_TIN, B.DOC_REF_ID, B.CORR_DOC_REF_ID, B.FI_ID, B.UPAT_ID, B.WARNING_FLAGS                                                                                  
                     		FROM PTP_UTPR_ATTR B, PTP_FILING_INFO F                                                                                                                                          
                             WHERE                                                                                                                                                                      
                             B.FI_ID = F.FI_ID                                                                                                                                                          
                             AND NOT EXISTS (SELECT 1 FROM UTPR_DOC_REF WHERE B.UPAT_ID = UTPR_DOC_REF.UPAT_ID)                                                                                         
                             AND B.IS_ACTIVE = 'Y'                                                                                                                                                      
                             ORDER BY B.CREATED_AT                                                                                                                                                      
                             )                                                                                                                                                                          
                     	LOOP                                                                                                                                                                              
                             L_RECORD_COUNT := L_RECORD_COUNT + 1;                                                                                                                                      
                                                                                                                                                                                                        
                             -- print progress to batch log                                                                                                                                             
                             IF MOD(L_RECORD_COUNT, 5000) = 0 THEN                                                                                                                                      
                                 UPDATE BATCH_LOG SET APP_LOG = 'PROCESSING RECORD: ' || L_RECORD_COUNT, LAST_UPD_AT = SYSDATE WHERE BTL_ID = L_BATCH_LOG_ID;                                           
                                 COMMIT;                                                                                                                                                                
                             END IF;                                                                                                                                                                    
                                                                                                                                                                                                        
                     		IF R.WARNING_FLAGS > 0 THEN                                                                                                                                                      
                     			-- Exception                                                                                                                                                                    
                                 L_RECORD_TYPE := 'E';                                                                                                                                                  
                     		ELSE                                                                                                                                                                             
                                 -- To Be Transmitted                                                                                                                                                   
                     			L_RECORD_TYPE := 'T';                                                                                                                                                           
                     		END IF;                                                                                                                                                                          
                                                                                                                                                                                                        
                             -- IF CORR_DOC_REF_ID IS NULL, THEN THIS IS A NEW OECD1 RECORD MISSING IN CTS, INSERT IT                                                                                   
                             IF R.CORR_DOC_REF_ID IS NULL THEN                                                                                                                                          
                                 INSERT INTO UTPR_DOC_REF VALUES                                                                                                                                        
                                 (UTPR_DOC_REF_SEQ.NEXTVAL, R.UPAT_ID, R.FI_ID, R.FCE_TIN, R.DOC_REF_ID, L_RECORD_TYPE,                                                                                 
                                 SYSDATE, 2, SYSDATE, 2);                                                                                                                                               
                                 CONTINUE;                                                                                                                                                              
                                                                                                                                                                                                        
                             ELSE                                                                                                                                                                       
                                 -- FIND THE UPAT_ID EXISTS IN CTS FOR THIS RECORD CHAIN                                                                                                                
                                 L_UPAT_ID := FIND_CTS_UPAT_ID(R.FCE_TIN, R.CORR_DOC_REF_ID);                                                                                                           
                                                                                                                                                                                                        
                                 -- IF UPAT_ID IS FOUND, FIND THE UPDR_ID FOR UPDATING                                                                                                                  
                                 IF L_UPAT_ID > 0 THEN                                                                                                                                                  
                                     SELECT MAX(UPDR_ID) INTO L_UPDR_ID FROM UTPR_DOC_REF WHERE UPAT_ID = L_UPAT_ID;                                                                                    
                                                                                                                                                                                                        
                                     --  UPDATE UTPR_DOC_REF IF RECORD FOUND                                                                                                                            
                                     UPDATE UTPR_DOC_REF                                                                                                                                                
                                         SET DOC_REF_ID = R.DOC_REF_ID,                                                                                                                                 
                                             UPAT_ID = R.UPAT_ID,                                                                                                                                       
                                             FI_ID = R.FI_ID,                                                                                                                                           
                                             FCE_TIN = R.FCE_TIN,                                                                                                                                       
                                             RECORD_TYPE = L_RECORD_TYPE,                                                                                                                               
                                             LAST_UPD_AT = SYSDATE,                                                                                                                                     
                                             LAST_UPD_BY = 2                                                                                                                                            
                                         WHERE UPDR_ID = L_UPDR_ID;                                                                                                                                     
                                                                                                                                                                                                        
                                 -- IF UPAT_ID CANNOT BE FOUND, THEN THE WHOLE RECORD CHAIN IS MISSING IN CTS, JUST INSERT THE CURRENT ACTIVE RECORD                                                    
                                 ELSIF L_UPAT_ID = -1 THEN                                                                                                                                              
                                     INSERT INTO UTPR_DOC_REF VALUES                                                                                                                                    
                                     (UTPR_DOC_REF_SEQ.NEXTVAL, R.UPAT_ID, R.FI_ID, R.FCE_TIN, R.DOC_REF_ID, L_RECORD_TYPE,                                                                             
                                     SYSDATE, 2, SYSDATE, 2);                                                                                                                                           
                                     CONTINUE;                                                                                                                                                          
                                                                                                                                                                                                        
                                 ELSE                                                                                                                                                                   
                                     RAISE_APPLICATION_ERROR(-20001, 'ERROR OCCURRED IN FIND_CTS_UPAT_ID');                                                                                             
                                                                                                                                                                                                        
                                 END IF;                                                                                                                                                                
                                                                                                                                                                                                        
                             END IF;                                                                                                                                                                    
                                                                                                                                                                                                        
                         END LOOP;                                                                                                                                                                      
                                                                                                                                                                                                        
                         IF L_RECORD_COUNT > 0 THEN                                                                                                                                                     
                             UPDATE BATCH_LOG SET APP_LOG = L_RECORD_COUNT || ' RECORDS WERE PROCESSED.', JOB_STS = 'S', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSD                                       
                     ATE WHERE BTL_ID = L_BATCH_LOG_ID;                                                                                                                                                 
                                                                                                                                                                                                        
                             OUT_RESULT_CODE := L_BATCH_LOG_ID;                                                                                                                                         
                         ELSE                                                                                                                                                                           
                             UPDATE BATCH_LOG SET APP_LOG = 'NO RECORD FOUND.', JOB_STS = 'S', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSDATE WHERE BTL_ID = L_BATCH                                       
                     _LOG_ID;                                                                                                                                                                           
                                                                                                                                                                                                        
                             OUT_RESULT_CODE := 0;                                                                                                                                                      
                         END IF;                                                                                                                                                                        
                     	COMMIT;                                                                                                                                                                           
                                                                                                                                                                                                        
                         UPD_CTS_UTPR_DOC_REF(L_CTS_RESULT);                                                                                                                                            
                                                                                                                                                                                                        
                         IF L_CTS_RESULT < 0 AND OUT_RESULT_CODE > 0 THEN                                                                                                                               
                             UPDATE BATCH_LOG SET ERR_LOG = 'ERROR OCCURRED IN UPD_CTS_UTPR_DOC_REF' WHERE BTL_ID = L_BATCH_LOG_ID;                                                                     
                         END IF;                                                                                                                                                                        
                                                                                                                                                                                                        
                         EXCEPTION                                                                                                                                                                      
                           WHEN OTHERS THEN                                                                                                                                                             
                             OUT_RESULT_CODE := -1;                                                                                                                                                     
                             ROLLBACK;                                                                                                                                                                  
                             UPDATE BATCH_LOG SET ERR_LOG = DBMS_UTILITY.FORMAT_ERROR_STACK, JOB_STS = 'E', TIME_ENDED = SYSDATE, LAST_UPD_AT = SYSDATE WHERE BTL                                       
                     _ID = L_BATCH_LOG_ID;                                                                                                                                                              
                                                                                                                                                                                                        
                             COMMIT;                                                                                                                                                                    
                                                                                                                                                                                                        
                     END UPD_UTPR_DOC_REF;                                                                                                                                                              

